import{_ as o,o as t,c,ag as s}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-11-05（地球与行星科学 · 火星冷季 HCl 异常，指向仍在进行的岩浆活动）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/earth-science/science-daily-2026-11-05-earth.md","filePath":"topics/earth-science/science-daily-2026-11-05-earth.md"}'),r={name:"topics/earth-science/science-daily-2026-11-05-earth.md"};function n(i,e,l,a,d,p){return t(),c("div",null,[...e[0]||(e[0]=[s('<h1 id="科学日报-·-2026-11-05-地球与行星科学-·-火星冷季-hcl-异常-指向仍在进行的岩浆活动" tabindex="-1">科学日报 · 2026-11-05（地球与行星科学 · 火星冷季 HCl 异常，指向仍在进行的岩浆活动） <a class="header-anchor" href="#科学日报-·-2026-11-05-地球与行星科学-·-火星冷季-hcl-异常-指向仍在进行的岩浆活动" aria-label="Permalink to &quot;科学日报 · 2026-11-05（地球与行星科学 · 火星冷季 HCl 异常，指向仍在进行的岩浆活动）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> — 第55期 ｜ 科学板块（地学/行星向 1 篇） 落盘说明：文件名带 <code>-earth</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-05-地球科学-·-1-1-火星冷季、阿尔巴山区域孤立的-ppb-级-hcl——活跃岩浆房的气体指纹" tabindex="-1">科学日报 2026-11-05（地球科学 · 1/1）：火星冷季、阿尔巴山区域孤立的 ppb 级 HCl——活跃岩浆房的气体指纹？ <a class="header-anchor" href="#科学日报-2026-11-05-地球科学-·-1-1-火星冷季、阿尔巴山区域孤立的-ppb-级-hcl——活跃岩浆房的气体指纹" aria-label="Permalink to &quot;科学日报 2026-11-05（地球科学 · 1/1）：火星冷季、阿尔巴山区域孤立的 ppb 级 HCl——活跃岩浆房的气体指纹？&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> ｜ DOI: 10.1126/sciadv.aeb9422 ｜ Science Advances (2026)</p></blockquote><ul><li>问题：火星一向被视为<strong>没有持续火山活动</strong>，但近年<strong>火星震</strong>的发现、以及<strong>数千万年以内火山活动</strong>的线索不断累积。<strong>SO₂ 一直未被探测到</strong>，而<strong>卤素气体（如 HCl）</strong> 的渗出可能是<strong>活跃岩浆房</strong>更灵敏的指示。</li><li>方法：分析 <strong>ACS（大气化学套件）</strong> 的<strong>大气 HCl 观测</strong>——重点看<strong>季节与空间分布</strong>（对比此前在<strong>近日点暖季、被归因于气溶胶—大气来源</strong>的广泛 ppb 级 HCl），并对照<strong>地表裂隙</strong>的成像。</li><li>结果（实测）： <ul><li>在<strong>远日点冷季、且孤立出现在阿尔巴山（Alba Mons）区域</strong>探测到 <strong>HCl</strong>；</li><li>识别出该区域<strong>新鲜的、宽度 &lt;1 米的新裂隙</strong>，据此解释为<strong>可能连通深部岩浆体的 HCl 通道</strong>；</li><li>作者认为<strong>最优解释是火星内部仍在进行岩浆过程</strong>。</li></ul></li><li>洞察（对本库 <code>earth-science</code> × <code>physics</code>）： <ol><li><strong>「用季节/空间分布做『排除性』判据，把广布来源与会聚来源分开」</strong>——全火星广布的 HCl 可能来自气溶胶，<strong>冷季 + 单点孤立</strong>才指向<strong>局部地质源</strong>；判据：<strong>当某信号有一个『大而平庸』的解释时，去找它在时空上的『不该出现』之处</strong>（呼应母题「<strong>否证性判据优于肯定性判据</strong>」）。</li><li><strong>「选一个其存在必须有源持续供给的示踪气体」</strong>——HCl 短寿命、需持续渗漏，比长寿命气体更能&quot;点名&quot;局部源；判据：<strong>要找源时，优先选半衰期短、无法靠背景解释的示踪物</strong>。</li><li><strong>与库内呼应</strong>：与 <code>topics/earth-science/</code> 的「行星/地球深部过程由地表可观测信号反推」一脉（如 <code>topics/earth-science/science-daily-2026-10-28-earth.md</code> 一类）。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/earth-science/index.md</code> ｜ <code>topics/physics/space-exploration-deep.md</code> ｜ 第55期 科学板块</p></blockquote><p>关键词：科学日报第55期、火星HCl探测、hydrogen chloride、活跃岩浆活动、阿尔巴山Alba Mons、ACS大气化学套件、ppb级HCl、远日点冷季、近日点暖季、气溶胶大气来源、孤立区域探测、宽度小于1米新裂隙、连通深部岩浆体的HCl通道、火星内部仍岩浆活动、SO2未被探测、火星震、季节空间分布排除法、半衰期短示踪气体、否证性判据优于肯定性判据、行星深部过程由地表信号反推</p><p>关联：<code>topics/earth-science/index.md</code>、<code>topics/earth-science/science-daily-2026-10-28-earth.md</code>、<code>topics/physics/space-exploration-deep.md</code>、<code>ScienceDaily/daily/2026-11-05.md</code></p>',10)])])}const u=o(r,[["render",n]]);export{h as __pageData,u as default};
